<?php
declare(strict_types=1);require_once __DIR__.'/../config/bootstrap.php';requireRole('parent');header('Content-Type: application/json; charset=utf-8');$uid=userId();$action=$_POST['action']??$_GET['action']??'list';
if($action==='link'){$token=trim($_POST['link_code']??'');checkCsrf($_POST['csrf']??null);$s=$pdo->prepare("SELECT id FROM users WHERE link_code=? AND role='student'");$s->execute([$token]);$student=$s->fetch();if(!$student){http_response_code(404);echo json_encode(['message'=>'Invalid student code.']);exit;} $s=$pdo->prepare('INSERT IGNORE INTO parent_student(parent_id,student_id) VALUES(?,?)');$s->execute([$uid,$student['id']]);echo json_encode(['success'=>true]);exit;}
$s=$pdo->prepare('SELECT u.id,u.full_name,u.email,u.xp,u.level,u.streak,u.link_code FROM parent_student ps JOIN users u ON u.id=ps.student_id WHERE ps.parent_id=?');$s->execute([$uid]);$children=$s->fetchAll();foreach($children as &$c){$q=$pdo->prepare('SELECT c.title_en,c.title_ar,p.percent_complete FROM progress p JOIN courses c ON c.id=p.course_id WHERE p.student_id=?');$q->execute([$c['id']]);$c['courses']=$q->fetchAll();}echo json_encode(['children'=>$children]);
